package com.triptales.app;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.BitmapFactory;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import android.widget.*;import androidx.core.app.ActivityCompat;import androidx.core.content.ContextCompat;import androidx.core.content.FileProvider;import java.io.*;
public class CameraActivity extends Activity{
 ImageView preview;Uri photoUri;File photoFile;static final int CAM=55;
 protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_camera);preview=findViewById(R.id.photoPreview);findViewById(R.id.captureButton).setOnClickListener(v->openCamera());}
 void openCamera(){if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.CAMERA},CAM);return;}try{File dir=new File(getFilesDir(),"photos");if(!dir.exists())dir.mkdirs();photoFile=new File(dir,"trip_"+System.currentTimeMillis()+".jpg");photoUri=FileProvider.getUriForFile(this,"com.triptales.app.fileprovider",photoFile);Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);i.putExtra(MediaStore.EXTRA_OUTPUT,photoUri);i.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(i,CAM);}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==CAM&&c==RESULT_OK&&photoFile!=null){preview.setImageBitmap(BitmapFactory.decodeFile(photoFile.getAbsolutePath()));Toast.makeText(this,"Saved in internal storage: "+photoFile.getName(),Toast.LENGTH_LONG).show();}}
}
